#!/usr/bin/env node
// Assert that src/lib/bindings.ts still describes the command and event surface declared in
// src-tauri/src/lib.rs.
//
// bindings.ts is generated by a debug build that ran with no CLI arguments. Two properties of
// that guard combine badly: any argument-less run of *any* debug binary rewrites the file, and
// the file is prefixed `// @ts-nocheck`, so a stale binary can silently revert the whole TS API
// surface with nothing failing afterwards. tsc will not catch it; the only symptom is a runtime
// "command not found" in the webview.
//
// This is a static cross-check, so it needs no build and no toolchain: it reads the
// `collect_commands!` / `collect_events!` lists out of lib.rs and compares them with what the
// generated file actually exports.

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const libRs = readFileSync(join(root, "src-tauri/src/lib.rs"), "utf8");
const bindings = readFileSync(join(root, "src/lib/bindings.ts"), "utf8");

function macroList(source, macro) {
  const start = source.indexOf(`${macro}![`);
  if (start === -1) throw new Error(`${macro}! not found in lib.rs`);
  const open = source.indexOf("[", start);
  let depth = 0;
  let end = -1;
  for (let i = open; i < source.length; i++) {
    if (source[i] === "[") depth++;
    else if (source[i] === "]") {
      depth--;
      if (depth === 0) {
        end = i;
        break;
      }
    }
  }
  if (end === -1) throw new Error(`${macro}! is not closed`);
  return source
    .slice(open + 1, end)
    .split("\n")
    .map(line => line.trim())
    .filter(line => line && !line.startsWith("//"))
    .flatMap(line => line.split(","))
    .map(entry => entry.trim())
    .filter(Boolean)
    // `permissions::check_permissions` and `check_permissions` name the same command.
    .map(entry => entry.split("::").pop());
}

const snakeToKebab = name => name.replace(/_/g, "-");
const pascalToKebab = name =>
  name
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/([A-Z])([A-Z][a-z])/g, "$1-$2")
    .toLowerCase();

const declaredCommands = new Set(macroList(libRs, "collect_commands"));
const declaredEvents = new Set(macroList(libRs, "collect_events").map(pascalToKebab));

const exportedCommands = new Set(
  [...bindings.matchAll(/TAURI_INVOKE\(\s*"([a-z0-9_]+)"/g)].map(m => m[1])
);

const eventsBlock = bindings.match(/__makeEvents__<\{[\s\S]*?\}>\(\{([\s\S]*?)\}\)/);
if (!eventsBlock) {
  console.error("check-bindings: could not find the __makeEvents__ map in bindings.ts");
  process.exit(1);
}
const exportedEvents = new Set(
  [...eventsBlock[1].matchAll(/:\s*"([a-z0-9-]+)"/g)].map(m => m[1])
);

const problems = [];
const compare = (what, declared, exported) => {
  for (const name of declared) {
    if (!exported.has(name)) problems.push(`${what} "${name}" is declared in lib.rs but missing from bindings.ts`);
  }
  for (const name of exported) {
    if (!declared.has(name)) problems.push(`${what} "${name}" is in bindings.ts but no longer declared in lib.rs`);
  }
};

compare("command", declaredCommands, exportedCommands);
compare("event", declaredEvents, exportedEvents);

// `snakeToKebab` is only here to keep the two naming helpers side by side; commands travel as
// snake_case on both sides, so nothing calls it. Referencing it keeps linters quiet without a
// disable comment.
void snakeToKebab;

if (problems.length > 0) {
  console.error("bindings.ts does not match the command/event surface in lib.rs:\n");
  for (const p of problems) console.error(`  - ${p}`);
  console.error(
    "\nRegenerate it: from src-tauri/, run a debug build with no CLI arguments" +
      " (`pnpm tauri dev`), then diff src/lib/bindings.ts before committing."
  );
  process.exit(1);
}

console.log(
  `bindings.ts matches lib.rs: ${declaredCommands.size} commands, ${declaredEvents.size} events.`
);
